import{_ as t,o as n,c as a,ah as s}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Parcours apprenant","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/learner-journey.md","filePath":"src/guide/learner-journey.md"}'),r={name:"guide/learner-journey.md"};function i(o,e,l,p,c,u){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="parcours-apprenant" tabindex="-1">Parcours apprenant <a class="header-anchor" href="#parcours-apprenant" aria-label="Permalink to &quot;Parcours apprenant&quot;">​</a></h1><p>De la candidature au Parcours Canopé, voici le chemin complet d&#39;un apprenant dans Kura. Chaque étape est déclenchée par un acteur identifié et laisse une trace.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Site NextBoxx</span></span>
<span class="line"><span>    │  dépôt (API)</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Candidature ──► Entretien ──► Test QCM ──► Décision</span></span>
<span class="line"><span>                                              │ admis</span></span>
<span class="line"><span>                                              ▼</span></span>
<span class="line"><span>                                        Inscription</span></span>
<span class="line"><span>                                              │</span></span>
<span class="line"><span>                        consentements ──► Convention ──► 1re tranche</span></span>
<span class="line"><span>                                              │              │</span></span>
<span class="line"><span>                                              │              ├─► compte Sève</span></span>
<span class="line"><span>                                              │              └─► livret d&#39;accueil</span></span>
<span class="line"><span>                                              ▼</span></span>
<span class="line"><span>                                 Formation (Sève) · présence · notes</span></span>
<span class="line"><span>                                              │</span></span>
<span class="line"><span>                        mi-parcours (40 %) ──► solde (30 %)</span></span>
<span class="line"><span>                                              │</span></span>
<span class="line"><span>                                              ▼</span></span>
<span class="line"><span>                                   Certificat ──► Canopé</span></span></code></pre></div><h2 id="_1-depot-de-la-candidature" tabindex="-1">1. Dépôt de la candidature <a class="header-anchor" href="#_1-depot-de-la-candidature" aria-label="Permalink to &quot;1. Dépôt de la candidature&quot;">​</a></h2><p>Le candidat choisit un référentiel publié et un format sur le site NextBoxx, puis dépose son dossier (motivation, pièces éventuelles, signalement de minorité, code apporteur facultatif). Le site transmet à Kura par API.</p><p>Kura crée ou réutilise le compte, attribue le rôle <strong>Candidat</strong> et ouvre la candidature. Le candidat reçoit un accusé de réception avec un lien pour choisir son mot de passe s&#39;il est nouveau.</p><p>Une seule candidature en cours par compte, quel que soit le référentiel. Après un refus, un nouveau dépôt est possible au bout de <strong>7 jours</strong>, rattaché au même compte et lié à la précédente.</p><h2 id="_2-entretien" tabindex="-1">2. Entretien <a class="header-anchor" href="#_2-entretien" aria-label="Permalink to &quot;2. Entretien&quot;">​</a></h2><p>Un Conseiller admissions prend le dossier dans la file partagée et en devient responsable. L&#39;entretien est à mener sous <strong>5 jours ouvrés</strong> ; seul le conseiller responsable le clôt, avec un compte rendu interne. La clôture ouvre le test.</p><p>Les jours ouvrés vont du lundi au vendredi, hors jours fériés saisis par l&#39;Administrateur. Une tâche quotidienne relance une fois chaque étape en retard.</p><h2 id="_3-test-d-admission" tabindex="-1">3. Test d&#39;admission <a class="header-anchor" href="#_3-test-d-admission" aria-label="Permalink to &quot;3. Test d&#39;admission&quot;">​</a></h2><p>Le lien part à la clôture de l&#39;entretien si la banque QCM du référentiel est validée. Caractéristiques :</p><ul><li>lien à usage unique, sans connexion, fenêtre de <strong>48 h</strong> pour commencer ;</li><li><strong>2 tentatives</strong>, <strong>45 minutes</strong> chacune à partir de l&#39;ouverture ;</li><li><strong>10 questions</strong> tirées parmi les 20 validées ; la 2e tentative exclut celles de la 1re ;</li><li>score affiché dès la soumission, <strong>seuil indicatif de 60 %</strong> (6/10) ;</li><li>une tentative réussie clôt le test ; sinon il se clôt après la 2e.</li></ul><p>Le score est indicatif : le dossier va en décision quel que soit le résultat. En cas de lien expiré, le Conseiller est relancé une fois, puis envoie un nouveau lien ou clôt le test.</p><h2 id="_4-decision" tabindex="-1">4. Décision <a class="header-anchor" href="#_4-decision" aria-label="Permalink to &quot;4. Décision&quot;">​</a></h2><p>Le conseiller responsable rend une <strong>décision motivée sous 3 jours ouvrés</strong> après le test. Le motif reste interne ; le candidat est prévenu par email.</p><table tabindex="0"><thead><tr><th>Décision</th><th>Effet</th></tr></thead><tbody><tr><td><strong>Admis</strong></td><td>Rôle Apprenant, création de l&#39;inscription, cohorte choisie ou placement ultérieur</td></tr><tr><td><strong>Refusé</strong></td><td>Dossier clos, sans paiement ni accès Sève ; conservé 12 mois puis anonymisé</td></tr></tbody></table><p>La lettre de décision est générée et jointe à l&#39;email, puis téléchargeable depuis « Mes candidatures ».</p><h2 id="_5-inscription-consentements-et-convention" tabindex="-1">5. Inscription, consentements et convention <a class="header-anchor" href="#_5-inscription-consentements-et-convention" aria-label="Permalink to &quot;5. Inscription, consentements et convention&quot;">​</a></h2><p>L&#39;inscription naît à l&#39;admission, au statut <strong>en attente de signature</strong>. Le Conseiller choisit une cohorte ouverte ou confirmée, pas encore commencée, avec une place et un tarif pour le format ; à défaut, le Coordinateur place l&#39;apprenant avant la signature.</p><p>Avant de signer, l&#39;apprenant :</p><ul><li>confirme ou change son <strong>format</strong> parmi ceux tarifés pour la cohorte ;</li><li>donne <strong>deux consentements distincts</strong> : réutilisation pédagogique du projet tutoré et droit à l&#39;image ;</li><li>pour un mineur, fait signer son <strong>représentant légal</strong> par un lien email sans compte, valable 7 jours.</li></ul><p>La Convention se signe avec un <strong>code à 6 chiffres</strong> reçu par email : valable 15 minutes, 5 essais, usage unique. La contre-signature edPage est automatique ou manuelle selon le réglage de l&#39;Administrateur. Elle fige le format, la cohorte et le prix, active l&#39;inscription et produit le PDF scellé <code>CONV-NB-AAAA-XXX</code>.</p><h2 id="_6-premiere-tranche-et-entree-dans-seve" tabindex="-1">6. Première tranche et entrée dans Sève <a class="header-anchor" href="#_6-premiere-tranche-et-entree-dans-seve" aria-label="Permalink to &quot;6. Première tranche et entrée dans Sève&quot;">​</a></h2><p>Après la contre-signature, la première facture (30 %) est émise. Dès que <strong>toutes les parts</strong> de cette tranche sont payées — apprenant et financeur — Kura :</p><ul><li>provisionne le compte Sève (SSO, sans mot de passe Moodle) ;</li><li>inscrit l&#39;apprenant au cours de sa cohorte ;</li><li>génère et envoie le <strong>livret d&#39;accueil</strong> <code>LA-NB-AAAA-XXX</code>.</li></ul><p>Une suspension ou une réactivation est répercutée sur Sève. Un changement de cohorte remplace la convention et produit un nouveau livret.</p><h2 id="_7-formation-presence-et-resultats" tabindex="-1">7. Formation, présence et résultats <a class="header-anchor" href="#_7-formation-presence-et-resultats" aria-label="Permalink to &quot;7. Formation, présence et résultats&quot;">​</a></h2><p>L&#39;apprenant suit sa formation sur Sève. La présence des séances virtuelles et les notes par bloc remontent dans Kura chaque heure. Le présentiel est saisi par un Formateur Principal.</p><ul><li>Alerte au Coordinateur et à l&#39;apprenant au-delà de <strong>30 % d&#39;absence</strong>.</li><li>Notes sur 20 par bloc ; moyenne pondérée par la durée des blocs.</li><li>Repêchage possible pour un bloc sous 10/20, 15 jours après la dernière note, 2 fois au plus.</li><li>Projet tutoré, soutenance et stage saisis par le Coordinateur ; ces notes restent hors moyenne.</li></ul><h2 id="_8-facturation-du-parcours" tabindex="-1">8. Facturation du parcours <a class="header-anchor" href="#_8-facturation-du-parcours" aria-label="Permalink to &quot;8. Facturation du parcours&quot;">​</a></h2><p>Les tranches de 40 % (mi-parcours) et 30 % (fin) sont émises au fil de l&#39;eau, 15 jours avant leur échéance, avec les rappels J-15, J-7 et J-1. Le détail de la chronologie d&#39;impayé est dans <a href="/kura-guide/guide/billing.html">Facturation</a>.</p><h2 id="_9-certificat-et-parcours-canope" tabindex="-1">9. Certificat et Parcours Canopé <a class="header-anchor" href="#_9-certificat-et-parcours-canope" aria-label="Permalink to &quot;9. Certificat et Parcours Canopé&quot;">​</a></h2><p>Le certificat est délivré quand <strong>les quatre conditions</strong> sont réunies :</p><ol><li>moyenne ≥ 10/20 ;</li><li>aucun bloc &lt; 8/20 ;</li><li>soutenance validée ;</li><li>solde intégralement payé.</li></ol><p>Aucune condition ne compense une autre. Le certificat <code>CERT-NB-AAAA-XXX</code> est figé, scellé par empreinte SHA-256 et signé au nom du président du jury. Sa délivrance termine l&#39;inscription, retire l&#39;apprenant du cours de sa cohorte, fait passer le compte au statut <strong>Canopé</strong> et l&#39;inscrit au Parcours Canopé.</p><p>En cas d&#39;interruption avec au moins un bloc validé, le Coordinateur délivre une <strong>attestation partielle</strong> <code>ATP-NB-AAAA-XXX</code>, jamais un certificat partiel. Un <strong>relevé de compétences</strong> accompagne le certificat ou l&#39;attestation.</p><h2 id="ce-que-voit-l-apprenant" tabindex="-1">Ce que voit l&#39;apprenant <a class="header-anchor" href="#ce-que-voit-l-apprenant" aria-label="Permalink to &quot;Ce que voit l&#39;apprenant&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Espace</th><th>Contenu</th></tr></thead><tbody><tr><td>Mes candidatures</td><td>Étapes, décision, lettre de décision</td></tr><tr><td>Mon inscription</td><td>Cohorte, format, prix, convention, consentements</td></tr><tr><td>Mes documents</td><td>Conventions, livret, factures, avoirs, certificat, attestation, relevé</td></tr><tr><td>Mes factures</td><td>Échéances, paiements, PDF</td></tr><tr><td>Mes rôles</td><td>Demandes de rôle et statut</td></tr><tr><td>Mes événements</td><td>Inscriptions aux événements</td></tr><tr><td>Mes projets / Mes financements</td><td>L&#39;Éclosion et apports d&#39;événement, selon les rôles</td></tr></tbody></table>`,39)])])}const h=t(r,[["render",i]]);export{m as __pageData,h as default};
